async ({ workspace: { read, edit } }, p: { fn: string }) => {
  const f = await read("src/renderers/context-entries.ts");
  const ls = f.content.split("\n");
  const a = (s: string) => ls.find((l) => l.includes(s))!.split("|")[0];
  return edit("src/renderers/context-entries.ts", {
    revision: f.revision,
    changes: [
      { kind: "insertBefore", anchor: a('import type { NoticeDetails } from "../context/notices.js";'), content: 'import { IMITATED_CALL_TYPE, type ImitatedCallDetails } from "../context/imitated-calls.js";' },
      { kind: "insertBefore", anchor: a("/** Saved-function changes the system prompt does not list yet"), content: p.fn },
      { kind: "insertAfter", anchor: a("pi.registerMessageRenderer(NOTICE_TYPE, renderNotice);"), content: "  pi.registerMessageRenderer(IMITATED_CALL_TYPE, renderImitatedCall);" },
    ],
  });
}
